) AS v(id, kode, komoditas_kode, pasar_id, tipe, harga, satuan, kualitas, sumber, status, lat, lng, dalam_geofence, kode_pedagang, dicatat_pada, petugas_id, divalidasi_oleh, divalidasi_pada, dipublikasi_oleh, dipublikasi_pada, alasan_penolakan, ditolak_oleh, ditolak_pada, deviasi_pct, skor_anomali, flag_validasi, foto_url, dibuat_pada, diupdate_pada)
CROSS JOIN _geser_harga AS g
ON CONFLICT (kode) DO UPDATE SET
    divalidasi_pada = CASE WHEN entri_harga.status = EXCLUDED.status THEN EXCLUDED.divalidasi_pada
                      ELSE entri_harga.divalidasi_pada + (EXCLUDED.dicatat_pada - entri_harga.dicatat_pada) END,
    dipublikasi_pada = CASE WHEN entri_harga.status = EXCLUDED.status THEN EXCLUDED.dipublikasi_pada
                       ELSE entri_harga.dipublikasi_pada + (EXCLUDED.dicatat_pada - entri_harga.dicatat_pada) END,
    ditolak_pada = CASE WHEN entri_harga.status = EXCLUDED.status THEN EXCLUDED.ditolak_pada
                   ELSE entri_harga.ditolak_pada + (EXCLUDED.dicatat_pada - entri_harga.dicatat_pada) END,
    dibuat_pada = CASE WHEN entri_harga.status = EXCLUDED.status THEN EXCLUDED.dibuat_pada
                  ELSE entri_harga.dibuat_pada + (EXCLUDED.dicatat_pada - entri_harga.dicatat_pada) END,
    diupdate_pada = CASE WHEN entri_harga.status = EXCLUDED.status THEN EXCLUDED.diupdate_pada
                    ELSE entri_harga.diupdate_pada + (EXCLUDED.dicatat_pada - entri_harga.dicatat_pada) END,
    dicatat_pada = EXCLUDED.dicatat_pada
 WHERE entri_harga.dicatat_pada IS DISTINCT FROM EXCLUDED.dicatat_pada;

